class Base { int common_data; };

// Intermediate classes use 'virtual'
class Derived1 : virtual public Base {
    // Compiler embeds pointer/offset to Base subobject (vtable required)
    int d1_data;
};

class Derived2 : virtual public Base {
    // Compiler embeds pointer/offset to Base subobject (vtable required)
    int d2_data;
};

// Only ONE Base instance exists in MostDerived
class MostDerived : public Derived1, public Derived2 {
    // Base subobject placement is resolved here
};
